// Generates the extended continuity proposal (16:9 PDF, 10 pages) from the portal data, using a local Chrome or Edge.
// Page 2 embeds the sales map generated by export_map_pdf.mjs, so both documents show the same figures.
import {execFileSync} from 'node:child_process';
import {existsSync, mkdtempSync, readFileSync, rmSync, writeFileSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {dirname, join, resolve} from 'node:path';
import {fileURLToPath, pathToFileURL} from 'node:url';
import vm from 'node:vm';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const dist = join(root, 'dist');
const args = process.argv.slice(2);
const option = name => {const i = args.indexOf(name);return i >= 0 ? args[i + 1] : undefined;};
const output = resolve(option('--output') || join(dist, 'assets', 'propuesta-continuidad-tuenti.pdf'));
const keepHtml = option('--html');

const context = {window: {}};
vm.runInNewContext(readFileSync(join(dist, 'content.js'), 'utf8'), context);
const catalog = context.window.TuentiCatalog;
const impact = context.window.TuentiImpact;
const team = context.window.TuentiTeam;
const development = JSON.parse(readFileSync(join(dist, 'data', 'development.json'), 'utf8'));
const incidents = JSON.parse(readFileSync(join(dist, 'data', 'incidents.json'), 'utf8'));

const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const asset = name => pathToFileURL(join(dist, 'assets', name)).href;
const months = ['ene','feb','mar','abr','may','jun','jul','ago','sep','oct','nov','dic'];
const monthLabel = month => months[Number(month.slice(5)) - 1];
const quarterLabel = quarter => `${quarter.slice(6)}Q ${quarter.slice(0,4)}`;
const loaded = development.quarters.filter(q => q.hasData);
const delivered = loaded.flatMap(q => q.highlights.map(h => ({...h, quarter: q.quarter})));
const fronts = loaded.reduce((sum, q) => sum + q.workstreams.length, 0);
const reported = incidents.months.filter(m => m.hasData);
const maxMonth = Math.max(...reported.map(m => m.total));
const byCategory = incidents.totals.byCategory;
const asOf = development.asOf.split('-').reverse().join('/');
const period = `${quarterLabel(loaded[0].quarter)} — ${quarterLabel(loaded.at(-1).quarter)}`;
const incidentPeriod = `${monthLabel(reported[0].month)} — ${monthLabel(reported.at(-1).month)} ${reported.at(-1).month.slice(0,4)}`;
const fact = label => team.facts.find(([, l]) => l === label)?.[0] || '';
// Sales wording, as in the map: the portal says "registradas"; the proposal speaks of handled incidents.
const factLabels = {'Incidencias registradas': 'Incidencias gestionadas'};
const kindLabels = {incidencia: 'Correcciones', mantenimiento: 'Mantenimiento'};
const byKind = development.kinds.map(k => ({...k, label: kindLabels[k.id] || k.label, count: delivered.filter(h => h.kind === k.id).length})).filter(k => k.count).sort((a, b) => b.count - a.count);
const peak = reported.find(m => m.total === maxMonth);
const peakCategory = incidents.categories.map(c => ({...c, count: peak.counts[c.id]})).sort((a, b) => b.count - a.count)[0];
const peakNote = peakCategory.count / peak.total > .5 ? `${monthLabel(peak.month).replace(/^./, c => c.toUpperCase())}: ${peakCategory.count} de ${peak.total} por una afectación masiva de ${peakCategory.label}.` : '';
const frontLabels = {
  'Mantenimiento, performance y mejoras internas': 'Mantenimiento y performance',
  'Implementación de desarrollos': 'Desarrollos',
  'DCP · segundo medio de pago': 'DCP · 2.º medio de pago',
  'DCP · segundo medio de pago: implementación': 'DCP · 2.º medio de pago (impl.)',
  'Referidos · Fase 2: implementación': 'Referidos · Fase 2 (impl.)',
  'Mejoras de acceso y medición': 'Acceso y medición',
  'Integración CI360 en la app Tuenti': 'CI360 en la app',
  'Super APP Tuenti + Pegasus': 'Super APP + Pegasus'
};

// Jira highlights for the given services; pick keeps only the titles that match, in that order.
const hitos = (services, pick) => {
  const list = delivered.filter(h => services.includes(h.service));
  return pick ? pick.map(p => list.find(h => p.test(h.title))).filter(Boolean) : list;
};
const hitoCount = services => delivered.filter(h => services.includes(h.service)).length;
const proofs = (items, extra = []) => `<ul class="proofs">${items.map(h => `<li><span>${esc(h.title)}</span><small>${esc(quarterLabel(h.quarter))}</small></li>`).join('')}${extra.map(([text, when]) => `<li><span>${esc(text)}</span><small>${esc(when)}</small></li>`).join('')}</ul>`;
const kpis = list => `<div class="kpis">${list.map(([n, label]) => `<div><strong>${esc(n)}</strong><span>${esc(label)}</span></div>`).join('')}</div>`;

const TOTAL = 10;
let number = 0;
const page = (label, body, {plain = false} = {}) => {
  number += 1;
  if(plain) return `<section class="page plain">${body}</section>`;
  return `<section class="page"><header><img src="${asset('tsoft-logo.png')}" alt="TSOFT"><span>${esc(label)}</span></header>${body}<footer><span>TSOFT | Tuenti | Propuesta de continuidad | Octubre 2026</span><b>${String(number).padStart(2,'0')} / ${String(TOTAL).padStart(2,'0')}</b></footer></section>`;
};
const service = ({label, title, subtitle, left, scenario, impact: effect, response}) => page(label, `<h1>${esc(title)}</h1><p class="sub">${esc(subtitle)}</p><div class="cols"><div class="left">${left}</div><div class="right"><span class="kicker">Escenario sin capacidad de respuesta</span><p class="scenario">${esc(scenario)}</p><span class="kicker">Impacto operativo</span><p class="effect">${esc(effect)}</p><span class="kicker">Respuesta del equipo propuesta</span><p class="response">${esc(response)}</p></div></div>`);

function mapHtml(work) {
  const file = join(work, 'mapa.html');
  execFileSync(process.execPath, [join(root, 'scripts', 'export_map_pdf.mjs'), '--output', join(work, 'mapa.pdf'), '--html', file], {stdio: 'ignore'});
  return readFileSync(file, 'utf8');
}

function build(map) {
  const pages = [];
  pages.push(page('Propuesta ejecutiva', `<div class="cover"><h1>Tuenti: continuidad del acceso,<br>las promociones y la medición</h1><p class="sub">Conocimiento técnico y funcional para sostener recorridos clave</p><p class="lead">Nuestro equipo construyó y sostiene buena parte del recorrido: app, login, servicios, procesos automáticos y medición. Ese conocimiento permite localizar el punto de falla, coordinar la recuperación y validar el resultado con las áreas responsables.</p>
<div class="facts">${team.facts.map(([n, label, detail]) => `<div><strong>${esc(n)}</strong><span>${esc(factLabels[label] || label)}</span><small>${esc(detail)}</small></div>`).join('')}</div>
<div class="axes"><b>Identidad y acceso / Gamificación y operación / Instrumentación y medición</b><small>Base: historial de repositorios con autor TSOFT, Jira (${esc(development.source.label)}) y registro Remedy. Datos al ${esc(asOf)}. Escenarios de impacto sujetos a validación.</small></div></div>`));

  pages.push(page('', `<iframe title="Mapa del ecosistema" srcdoc="${esc(map)}"></iframe>`, {plain: true}));

  // The game row also counts the gamification backend.
  const rowServices = {oraculo: ['oraculo', 'gaming']};
  const cell = value => `<td class="lv lv-${value.toLowerCase()}">${esc(value)}</td>`;
  const delivery = id => {
    const count = hitoCount(rowServices[id] || [id]);
    const category = catalog[id]?.incidentCategory;
    return [count ? `${count} hito${count === 1 ? '' : 's'}` : '', id === 'gtm' ? `${fact('Tags GTM en la app')} tags` : '', category ? `${byCategory[category]} incidencias` : ''].filter(Boolean).join(' · ') || 'Soporte vigente';
  };
  pages.push(page('Evaluación de impacto', `<h1>Mapa de calor de capacidades</h1><p class="sub">Impacto potencial sobre clientes, operación y calidad de la información</p><p class="intro">Ante una incidencia sin resolución; la evaluación no representa probabilidad de falla. La última columna muestra lo que el equipo ya entregó o gestionó en cada capacidad.</p>
<table class="heat"><thead><tr><th>Capacidad</th><th>Experiencia<br>del cliente</th><th>Operación<br>y campañas</th><th>Medición<br>y análisis</th><th>Motivo principal</th><th>Trayectoria del equipo</th></tr></thead><tbody>${impact.map(([id, name, a, b, c, why]) => `<tr><td class="name">${esc(name)}</td>${cell(a)}${cell(b)}${cell(c)}<td class="why">${esc(why)}</td><td class="done">${esc(delivery(id))}</td></tr>`).join('')}</tbody></table>
<p class="legend">Alto: puede bloquear el proceso. Medio: limita su ejecución o seguimiento. Bajo: efecto indirecto en esa dimensión. Hitos: Jira, ${esc(period)}. Incidencias: Remedy, ${esc(incidentPeriod)}.</p>`));

  const idp = catalog.idp;
  pages.push(service({label: 'Identidad y acceso', title: 'Identidad y acceso', subtitle: 'El login sostiene la entrada del cliente a sus gestiones',
    left: `<span class="kicker">Contexto de uso</span><h2>Puerta de entrada a Tuenti</h2><p class="note">Frontend y backend de autenticación.</p>
${kpis([[idp.commits[0].count, `commits con autor TSOFT · ${idp.commits[0].repo}`], [String(byCategory.identidad), 'incidencias de identidad y registro gestionadas']])}
<img class="shot login" src="${asset('idp-login.png')}" alt="">
<span class="kicker">Lo que ya entregamos</span>${proofs(hitos(['idp'], [/Olvidé/, /3 correcciones/, /íconos/]))}`,
    scenario: 'Una incidencia impide solicitar o validar el código de acceso, o completar la autenticación.',
    impact: 'El cliente no puede ingresar y debe postergar sus gestiones. Pueden aumentar el abandono del recorrido y las consultas a soporte.',
    response: 'Seguir el caso desde la pantalla y la validación de línea hasta el código y la sesión; verificar en web y móvil el ingreso y los errores previstos.'}));

  pages.push(service({label: 'Gamificación', title: 'Gamificación | Oráculo', subtitle: 'La experiencia promocional depende de reglas y servicios coordinados',
    left: `<span class="kicker">Contexto de uso</span><h2>Ruleta promocional</h2><p class="note">Experiencia y servicios de backend desarrollados por el equipo.</p>
<div class="flow"><span>Participante</span><i>→</i><span>Tiros disponibles</span><i>→</i><span>Juego y resultado</span><i>→</i><span>Premio y canje</span></div>
${kpis([['+13', 'microservicios nuevos de backend'], ['+10', 'correcciones en la experiencia de juego'], [String(hitoCount(['oraculo', 'gaming'])), `hitos en Jira · ${period}`]])}
<span class="kicker">Lo que ya entregamos</span>${proofs(hitos(['oraculo', 'gaming'], [/máquina de estados/, /pase a producción/, /prueba de estrés/, /Rueda de beneficios/, /React Native/]))}`,
    scenario: 'El cliente no puede jugar o un canje queda sin una respuesta clara durante una campaña.',
    impact: 'Reclamos y revisión de participaciones o beneficios. La campaña puede perder efectividad mientras se recupera el circuito.',
    response: 'Revisar el mismo caso en participante, tiros, juego y canje; contrastar estados con el panel y validar el recorrido en la app móvil.'}));

  pages.push(service({label: 'Operación promocional', title: 'Clouders Panel y procesos de referidos', subtitle: 'La campaña necesita seguimiento, configuración y recuperación de casos',
    left: `<span class="kicker">Contexto de uso</span><h2>Gestión de campañas</h2><p class="note">Panel, microservicios y procesos automáticos. Inventario informado: 9 ITG + 2 SVC + 7 FCD.</p>
<div class="boxes"><div><b>Clouders Panel</b><span>Configuraciones · Vouchers · Estados y reportes</span></div><div><b>Referidos</b><span>Carga y validación · Altas y recargas · Actualización de estados</span></div></div>
<span class="kicker">Lo que ya entregamos</span>${proofs(hitos(['panel', 'referidos'], [/Pase a producción/, /login y roles/, /premiación automática/, /Fase 2 implementada/, /Misiones/, /panel de referidos/]), [['Clouders Panel: consultas de consumos de tiros y stock', '1Q 2026']])}`,
    scenario: 'Una tarea de referidos no actualiza estados o el panel impide consultar casos y ajustar configuraciones.',
    impact: 'Casos pendientes y conciliación manual, con demoras en beneficios o en la atención de reclamos. Menor visibilidad de la campaña.',
    response: 'Revisar archivos, tareas programadas y estados; conciliar pendientes con las reglas de referidos y validar su recuperación con el área operativa.'}));

  const tagged = delivered.filter(h => h.tags);
  const tagTotal = tagged.reduce((sum, h) => sum + h.tags, 0);
  const tagMax = Math.max(...tagged.map(h => h.tags));
  const gtm = catalog.gtm.metrics;
  pages.push(service({label: 'Instrumentación y medición', title: 'GTM | Información para decidir', subtitle: 'Medir recorridos exige mantener el etiquetado a medida que cambia la app',
    left: `<span class="kicker">Contexto de uso</span><h2>El etiquetado de la app es nuestro</h2><p class="note">El equipo implementó la medición de la app Tuenti, pantalla por pantalla.</p>
${kpis(gtm.map(([n, label]) => [n, label.toLowerCase()]))}
<span class="kicker">Tags entregados en el período · ${tagTotal}</span><div class="tags">${tagged.map(h => `<div><span>${esc(h.title.replace(/^Etiquetado de /, '').replace(/ \(en curso\)$/, ''))}<small>${esc(quarterLabel(h.quarter))}${/en curso/.test(h.title) ? ' · en curso' : ''}</small></span><i style="width:${Math.round(h.tags / tagMax * 140)}px"></i><b>${h.tags}</b></div>`).join('')}</div>
<div class="reach"><img src="${asset('analytics.png')}" alt=""><p><b>158.815 usuarios activos</b>2.222.310 visualizaciones y 4.842.938 eventos · Tuenti Web App, 25/09 al 22/10/2026. Volumen de la propiedad completa del reporte.</p></div>`,
    scenario: 'Un cambio de pantalla o navegación deja de registrar eventos o altera el significado de los datos enviados.',
    impact: 'Datos faltantes aunque la app siga operativa. La medición incompleta dificulta detectar abandonos y evaluar cambios o campañas.',
    response: 'Verificar el evento desde la pantalla y el puente web-móvil hasta su recepción en Analytics; confirmar nombre y parámetros con el área solicitante.'}));

  const support = [
    ['Recargas automáticas y tarjetas', 'DCP / Recurrencia', 'Una recarga automática no se procesa o una tarjeta guardada no puede usarse: el cliente se queda sin saldo.', `Segundo medio de pago · baja automática de tarjetas · +${byCategory.dcp} casos gestionados`, 'Revisar integraciones y validar los escenarios de uso afectados.'],
    ['Avisos al celular', 'Push FCM', 'El cliente no se entera de que su recarga se hizo, falló o está por procesarse.', 'Aviso de próxima recarga corregido · mensaje al comprar un extra', 'Diagnosticar la integración y comprobar la entrega de notificaciones.'],
    ['Cambio de usuario', 'Circuito de backoffice', 'Gestiones demoradas y necesidad de intervención técnica para continuar.', 'Nuevo servicio de integración ChangeUser · mensaje de envío de pasaporte', 'Recuperar el circuito y comprobar el resultado para el operador.'],
    ['Despliegues y seguridad', 'Actualización de servicios y AppScan', 'Correcciones demoradas, hallazgos pendientes y mayor esfuerzo para liberar cambios.', 'Prueba de estrés de los pods · actualización de servicios y remediación AppScan en curso', 'Priorizar hallazgos, mantener dependencias y validar despliegues y regresiones.']
  ];
  pages.push(page('Soporte vigente', `<h1>Soporte que atraviesa la aplicación</h1><p class="sub">Recargas, avisos y gestiones que el cliente usa todos los meses</p>
<table class="support"><thead><tr><th>Capacidad en soporte</th><th>Qué puede quedar afectado</th><th>Lo que ya entregamos</th><th>Respuesta propuesta</th></tr></thead><tbody>${support.map(([name, detail, risk, done, answer]) => `<tr><td><b>${esc(name)}</b><small>${esc(detail)}</small></td><td>${esc(risk)}</td><td class="done">${esc(done)}</td><td class="answer">${esc(answer)}</td></tr>`).join('')}</tbody></table>
<p class="legend">Trabajo en curso informado por el responsable backend. La prioridad de los hallazgos depende de su severidad y estado de remediación. Casos: registro Remedy, ${esc(incidentPeriod)}.</p>`));

  // Only the last quarter is marked in progress; earlier open Features are shown as delivered quarters.
  const topCategories = incidents.categories.map(c => ({...c, count: byCategory[c.id]})).filter(c => c.count).sort((a, b) => b.count - a.count).slice(0, 5);
  pages.push(page('Trayectoria del equipo', `<h1>Trayectoria del equipo</h1><p class="sub">Entregas registradas en Jira y soporte registrado en Remedy</p>
<div class="track"><div><div class="track-head"><strong>+${delivered.length}</strong><span>hitos entregados en ${fronts} frentes de trabajo · ${esc(period)}</span></div>
<div class="quarters">${loaded.map((q, i) => {const current = q.status === 'open' && i === loaded.length - 1;return `<div class="${current ? 'open' : ''}"><b>${esc(quarterLabel(q.quarter))}${current ? '<em>en curso</em>' : ''}</b><span>${q.workstreams.length} frente${q.workstreams.length === 1 ? '' : 's'} · ${q.highlights.length} hito${q.highlights.length === 1 ? '' : 's'}</span><div>${q.workstreams.map(w => `<i>${esc(frontLabels[w.title] || w.title)}</i>`).join('')}</div></div>`;}).join('')}</div>
<span class="kicker">Hitos por tipo de trabajo</span><div class="stack">${byKind.map(k => `<i class="kind-${esc(k.id)}" style="flex:${k.count}"></i>`).join('')}</div><div class="kinds">${byKind.map(k => `<span><i class="kind-${esc(k.id)}"></i>${esc(k.label)} <b>${k.count}</b></span>`).join('')}</div></div>
<div class="incidents"><div class="track-head"><strong>+${incidents.quality.uniqueIncidents}</strong><span>incidencias gestionadas · ${esc(incidentPeriod)}</span></div>
<div class="bars">${reported.map(m => `<div><em>${m.total}</em><i style="height:${Math.max(3, Math.round(m.total / maxMonth * 150))}px"></i><small>${monthLabel(m.month)}</small></div>`).join('')}</div>${peakNote ? `<p class="peak">${esc(peakNote)}</p>` : ''}
<ul class="cats">${topCategories.map(c => `<li><span>${esc(c.label)}</span><b>${c.count}</b></li>`).join('')}</ul></div></div>`));

  pages.push(page('Propuesta de TSOFT', `<h1>Continuidad con capacidad de respuesta</h1><p class="sub">Acompañar la operación y la evolución de Tuenti con conocimiento del negocio</p>
<span class="kicker">Decisión propuesta</span><p class="decision">Proponemos dar continuidad al soporte de identidad, operación promocional y medición, con responsables definidos, atención priorizada de incidentes y un plan de evolución acordado.</p>
<div class="pillars"><div><span class="kicker">Operación</span><h3>Recuperar<br>los recorridos críticos</h3><p>Definir responsables y canales; priorizar incidentes según el recorrido y validar la recuperación.</p></div><div><span class="kicker">Conocimiento</span><h3>Conservar<br>contexto operativo</h3><p>Mantener reglas, dependencias y tareas programadas documentadas, con decisiones e incidentes registrados.</p></div><div><span class="kicker">Evolución</span><h3>Evolucionar<br>con trazabilidad</h3><p>Acordar prioridades de cambios, remediaciones y Analytics, con validación antes de cada liberación.</p></div></div>
<p class="record">Desde ${esc(quarterLabel(loaded[0].quarter))}: <b>+${delivered.length} hitos</b> entregados en ${fronts} frentes · <b>${esc(fact('Commits con autor TSOFT'))} commits</b> con autor TSOFT · <b>+${incidents.quality.uniqueIncidents} incidencias</b> gestionadas</p>
<div class="closing"><span class="kicker">Somos parte del equipo de Innovación</span><p>Aportamos experiencia técnica y funcional, creatividad y compromiso para seguir trabajando con ustedes y acompañarlos en esta nueva etapa.</p></div>`));
  if(number !== TOTAL) throw Error(`La propuesta tiene ${number} páginas y el pie indica ${TOTAL}.`);

  return `<!doctype html><html lang="es"><head><meta charset="utf-8"><title>Propuesta de continuidad Tuenti · TSOFT</title><style>
@page{size:1280px 720px;margin:0}
*{box-sizing:border-box;-webkit-print-color-adjust:exact;print-color-adjust:exact}
html,body{margin:0;background:#fff;color:#222126;font-family:'Segoe UI',Arial,sans-serif}
.page{position:relative;width:1280px;height:720px;padding:0 64px;overflow:hidden;break-after:page}
.page.plain{padding:0}.page iframe{display:block;width:1280px;height:720px;border:0}
.page>header{display:flex;align-items:center;justify-content:space-between;height:84px;border-bottom:1px solid #e4e2e8}
.page>header img{width:150px;height:44px;object-fit:contain;object-position:left}
.page>header span{font-size:11px;letter-spacing:.4px;text-transform:uppercase;color:#6c6672;margin-right:200px}
.page>footer{position:absolute;left:64px;right:84px;bottom:18px;display:flex;justify-content:space-between;font-size:9.5px;color:#6c6672}.page>footer b{font-size:12px;color:#3a3540}
h1{margin:26px 0 0;font-size:40px;line-height:1.1;letter-spacing:-1px}
.sub{margin:6px 0 0;font-size:21px;color:#d60027;font-weight:400}
.kicker{display:block;font-size:10.5px;font-weight:700;letter-spacing:.3px;text-transform:uppercase;color:#d60027;margin:16px 0 6px}
.cols{display:grid;grid-template-columns:560px 1fr;gap:56px;margin-top:4px}
.left h2{margin:0;font-size:22px;color:#d60027;letter-spacing:-.4px}.left .note{margin:2px 0 0;font-size:12px;color:#6c6672}
.right .scenario{margin:0;font-size:20px;line-height:1.3;font-weight:700}
.right .effect{margin:0;font-size:17px;line-height:1.4;color:#2b2830}
.right .response{margin:0;font-size:17px;line-height:1.4;color:#6c6672}
.right .kicker{margin-top:22px}
.kpis{display:flex;gap:10px;margin-top:12px}
.kpis div{flex:1;background:#f4f3f6;border-top:3px solid #d60027;border-radius:6px;padding:8px 12px}
.kpis strong{display:block;font-size:24px;line-height:1.1;letter-spacing:-.6px}.kpis span{display:block;font-size:10.5px;line-height:1.3;color:#5c5664;margin-top:2px}
.proofs{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:5px}
.proofs li{display:flex;justify-content:space-between;gap:14px;font-size:12px;line-height:1.35;padding-left:13px;position:relative}
.proofs li:before{content:'';position:absolute;left:0;top:6px;width:6px;height:6px;border-radius:50%;background:#d60027}
.proofs small{flex:none;font-size:10.5px;font-weight:600;color:#8a8491;padding-top:1px}
.shot.login{display:block;width:430px;height:150px;object-fit:cover;object-position:center 30%;margin:12px auto 0;border:1px solid #eceaf0;border-radius:6px}
.flow{display:flex;align-items:center;gap:6px;margin-top:12px}.flow span{flex:1;text-align:center;background:#f4f3f6;border-radius:6px;padding:9px 4px;font-size:13px;font-weight:700}.flow i{color:#d60027;font-style:normal}
.boxes{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:12px}.boxes div{background:#f4f3f6;border-radius:6px;padding:10px 14px}.boxes b{display:block;font-size:15px;margin-bottom:3px}.boxes span{font-size:11.5px;color:#5c5664;line-height:1.4}
.tags{display:flex;flex-direction:column;gap:5px}
.tags div{display:grid;grid-template-columns:270px 150px 30px;align-items:center;gap:8px}
.tags span{font-size:12px;line-height:1.25}.tags small{display:block;font-size:10px;color:#8a8491;font-weight:600}
.tags i{height:12px;background:#d60027;border-radius:2px}.tags b{font-size:14px}
.reach{display:flex;gap:14px;align-items:center;margin-top:14px;padding-top:12px;border-top:1px solid #eceaf0}
.reach img{width:190px;height:104px;object-fit:cover;object-position:top;border:1px solid #eceaf0;border-radius:4px}
.reach p{margin:0;font-size:11px;line-height:1.45;color:#5c5664}.reach b{display:block;font-size:17px;color:#d60027;margin-bottom:2px}
.intro{margin:14px 0 10px;font-size:13px;color:#6c6672}
.heat{width:100%;border-collapse:separate;border-spacing:5px 4px;margin-left:-5px}
.heat th{font-size:12px;text-align:center;line-height:1.2;padding-bottom:2px}.heat th:first-child,.heat th:nth-child(5),.heat th:last-child{text-align:left}
.heat td{height:38px;font-size:13.5px;border-radius:4px}
.heat .name{background:#f4f3f6;padding:0 12px;width:250px}
.heat .lv{width:132px;text-align:center;font-weight:700}
.lv-alto{background:#fde8ec;color:#c4002a}.lv-medio{background:#fdf1d8;color:#946000}.lv-bajo{background:#e5f0ea;color:#2a6b45}
.heat .why{font-size:11.5px;color:#5c5664;padding:0 6px;width:255px}
.heat .done{font-size:11.5px;font-weight:700;color:#2d4b73;background:#edf2f8;padding:0 10px}
.legend{margin:10px 0 0;font-size:10.5px;color:#6c6672}
.support{width:100%;border-collapse:collapse;margin-top:14px}
.support th{text-align:left;font-size:10.5px;color:#d60027;text-transform:uppercase;padding:0 12px 8px 0}
.support td{vertical-align:top;border-top:1px solid #e4e2e8;padding:11px 14px 11px 0;font-size:13.5px;line-height:1.38}
.support td:first-child{width:250px}.support td b{display:block;font-size:17px}.support td small{font-size:11px;color:#6c6672}
.support .done{font-weight:600;color:#2d4b73}.support .answer{color:#6c6672}
.track{display:grid;grid-template-columns:600px 1fr;gap:48px;margin-top:18px}
.track-head{display:flex;align-items:baseline;gap:10px}.track-head strong{font-size:36px;letter-spacing:-1px;color:#d60027}.track-head span{font-size:13px;color:#5c5664}
.quarters{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin-top:10px}
.quarters>div{background:#f4f3f6;border-top:3px solid #2d4b73;border-radius:6px;padding:9px 10px;min-height:186px}
.quarters>div.open{border-top-style:dashed}
.quarters b{display:block;font-size:15px}.quarters b em{font-style:normal;font-size:9.5px;font-weight:600;color:#8a8491;margin-left:5px}
.quarters span{display:block;font-size:11px;color:#5c5664;margin:1px 0 7px}
.quarters>div>div{display:flex;flex-direction:column;gap:4px}.quarters i{font-style:normal;font-size:10.5px;line-height:1.3;background:#fff;border-radius:3px;padding:2px 6px;color:#2d4b73;font-weight:600}
.stack{display:flex;gap:2px;height:10px;border-radius:4px;overflow:hidden}.stack i{display:block}
.kinds{display:flex;flex-wrap:wrap;gap:4px 14px;margin-top:8px}.kinds span{display:flex;align-items:center;gap:6px;font-size:11.5px;color:#5c5664}.kinds span i{width:9px;height:9px;border-radius:50%}.kinds b{color:#222126}
.kind-desarrollo{background:#2d4b73}.kind-evolucion{background:#5b84b1}.kind-medicion{background:#9fc1e3}.kind-incidencia{background:#6b6577}.kind-mantenimiento{background:#c9c5d1}
.bars{display:flex;align-items:flex-end;gap:8px;height:186px;margin-top:10px;border-bottom:1px solid #e4e2e8}
.bars>div{flex:1;display:flex;flex-direction:column;align-items:center;justify-content:flex-end;height:100%;gap:3px}
.bars i{width:100%;max-width:34px;background:#d60027;border-radius:3px 3px 0 0}.bars em{font-style:normal;font-size:11px;font-weight:700;color:#3a3540}.bars small{font-size:10.5px;color:#6c6672;padding-bottom:3px}
.peak{margin:8px 0 0;font-size:11.5px;color:#5c5664}
.cats{list-style:none;margin:10px 0 0;padding:0;display:grid;grid-template-columns:1fr 1fr;gap:3px 22px}
.cats li{display:flex;justify-content:space-between;font-size:11.5px;border-bottom:1px solid #f0eef3;padding:2px 0}.cats b{color:#3a3540}
.cover h1{margin-top:64px;font-size:48px}.cover .sub{margin-top:16px}
.cover .lead{margin:16px 0 0;font-size:18px;line-height:1.45;color:#3a3540;max-width:1050px}
.facts{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-top:36px}
.facts div{background:#28242e;color:#fff;border-radius:8px;padding:12px 16px;border-top:3px solid #d60027}
.facts strong{display:block;font-size:32px;line-height:1.05;letter-spacing:-1px}.facts span{display:block;font-size:12.5px;font-weight:600;margin-top:3px}.facts small{display:block;font-size:10.5px;color:#c9c3d0;margin-top:2px}
.axes{margin-top:34px;padding-top:14px;border-top:1px solid #e4e2e8}.axes b{display:block;font-size:18px}.axes small{display:block;margin-top:6px;font-size:10.5px;color:#6c6672}
.decision{margin:0;font-size:18px;line-height:1.4}
.pillars{display:grid;grid-template-columns:repeat(3,1fr);gap:40px;margin-top:8px}
.pillars h3{margin:0;font-size:21px;line-height:1.2}.pillars p{margin:8px 0 0;font-size:15px;line-height:1.4;color:#6c6672}
.record{margin:20px 0 0;padding:10px 16px;background:#f4f3f6;border-radius:6px;font-size:14px;color:#3a3540}.record b{color:#d60027}
.closing{margin-top:22px;padding-top:4px;border-top:1px solid #e4e2e8}.closing p{margin:0;font-size:21px;line-height:1.3;font-weight:700;color:#d60027}
</style></head><body>${pages.join('')}</body></html>`;
}

function findBrowser() {
  const candidates = [process.env.CHROME_PATH,
    'C:/Program Files/Google/Chrome/Application/chrome.exe', 'C:/Program Files (x86)/Google/Chrome/Application/chrome.exe',
    'C:/Program Files (x86)/Microsoft/Edge/Application/msedge.exe', 'C:/Program Files/Microsoft/Edge/Application/msedge.exe',
    '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome', '/usr/bin/google-chrome', '/usr/bin/chromium', '/usr/bin/chromium-browser'];
  const found = candidates.find(path => path && existsSync(path));
  if(!found) throw Error('No se encontró Chrome ni Edge. Definir CHROME_PATH con la ruta del navegador.');
  return found;
}

const work = mkdtempSync(join(tmpdir(), 'tuenti-propuesta-'));
try {
  const html = build(mapHtml(work));
  const file = join(work, 'propuesta.html');
  writeFileSync(file, html, 'utf8');
  if(keepHtml) writeFileSync(resolve(keepHtml), html, 'utf8');
  execFileSync(findBrowser(), ['--headless=new', '--disable-gpu', '--no-pdf-header-footer', '--allow-file-access-from-files', `--user-data-dir=${join(work, 'profile')}`, `--print-to-pdf=${output}`, pathToFileURL(file).href], {stdio: 'ignore'});
  if(!existsSync(output)) throw Error('El navegador no generó el PDF.');
  console.log(`PDF generado: ${output}`);
} finally {
  rmSync(work, {recursive: true, force: true});
}
